#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, P;
    cin >> N >> M >> P;

    vector<int> row(N), col(M);
    iota(row.begin(), row.end(), 1);
    iota(col.begin(), col.end(), 1);

    for (int i = 0; i < P; ++i) {
        char op;
        int a, b;
        cin >> op >> a >> b;
        if (op == 'L') swap(row[a - 1], row[b - 1]);
        else swap(col[a - 1], col[b - 1]);
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            if (j) cout << ' ';
            cout << (row[i] - 1) * M + col[j];
        }
        cout << '\n';
    }

    return 0;
}
